rule Author {
	from
		a : BibTeX!Author (
			thisModule.authorSet->includes(a)
		)
	to
		out : DocBook!Para (
			content <- a.author
		)
}

rule UntitledEntry {
	from
		e : BibTeX!BibTeXEntry (
